// Fails when src/data/blogPosts.json no longer matches the curated copy in
// src/data/curated-blog.mjs.
//
// blogPosts.json is generated by `npm run build:blog`, but it is also the file
// the site imports and the only blog data committed to git. Editing the curated
// copy without rebuilding — or editing the generated JSON by hand — would ship
// copy that no longer reflects the source of truth, including the shared yard
// address and contact line. Rebuilding into a temp file in the same directory
// and diffing catches both.
//
// Run with: npm run check:blog:sync
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const script = fileURLToPath(new URL('./apply-blog-content.mjs', import.meta.url));
const repoRoot = path.dirname(path.dirname(script));
const shippedPath = path.join(repoRoot, 'src', 'data', 'blogPosts.json');
const tmpName = `.__blog-sync-${process.pid}.json`;
const tmpPath = path.join(repoRoot, 'src', 'data', tmpName);

try {
  const { spawnSync } = await import('node:child_process');
  const result = spawnSync(process.execPath, [script], {
    cwd: repoRoot,
    env: { ...process.env, BLOG_SOURCE: shippedPath, BLOG_OUT: tmpName },
    encoding: 'utf8',
  });
  assert.equal(
    result.status,
    0,
    `The curated blog copy failed its own checks:\n${result.stderr?.trim() || result.stdout?.trim()}`,
  );

  const shipped = JSON.parse(fs.readFileSync(shippedPath, 'utf8'));
  const rebuilt = JSON.parse(fs.readFileSync(tmpPath, 'utf8'));
  assert.equal(
    shipped.length,
    rebuilt.length,
    `blogPosts.json has ${shipped.length} articles but the curated copy has ${rebuilt.length}`,
  );

  const drift = [];
  for (const [index, article] of rebuilt.entries()) {
    const committed = shipped[index];
    assert.equal(committed.slug, article.slug, 'Article order differs from the curated copy');
    for (const field of Object.keys(article)) {
      if (JSON.stringify(committed[field]) !== JSON.stringify(article[field])) {
        drift.push(`${article.slug}: ${field}`);
      }
    }
  }

  assert.deepEqual(
    drift,
    [],
    `blogPosts.json is out of sync with src/data/curated-blog.mjs (run \`npm run build:blog\`):\n  ${drift.join('\n  ')}`,
  );
  console.log(`blogPosts.json matches the curated copy (${rebuilt.length} articles).`);
} finally {
  if (fs.existsSync(tmpPath)) fs.rmSync(tmpPath);
}